let scrollPending=false;function updateScroll(){if(scrollPending)return;scrollPending=true;requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.transform=`scaleX(${total>0?Math.min(1,scrollY/total):0})`;let active='project';for(const a of $$('#site-nav a')){const target=$(a.hash);if(target&&target.getBoundingClientRect().top<=140)active=target.id;}$$('#site-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+active));scrollPending=false;});}addEventListener('scroll',updateScroll,{passive:true});addEventListener('resize',updateScroll,{passive:true});updateScroll();
