function wireTabKeys(container){const buttons=$$('[role=tab]',container);buttons.forEach((b,i)=>b.addEventListener('keydown',e=>{let index;if(e.key==='ArrowRight'||e.key==='ArrowDown')index=(i+1)%buttons.length;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')index=(i-1+buttons.length)%buttons.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=buttons.length-1;else return;e.preventDefault();buttons[index].click();buttons[index].focus();}));}
