const storyViewport=$('.story-viewport'),storyPanels=$$('.story-track>.chapter'),storyTabs=$$('[data-chapter]');
let storyIndex=0,storyTimer=0,storyVisible=false,storyPaused=false,storyHovered=false,storyFocused=false;
const storyNames=['启愿','破界','笃行','新程'];
function sizeStory(){storyViewport.style.height=Math.ceil(storyPanels[storyIndex].getBoundingClientRect().height)+'px';}
function updateStoryAutoplay(){const stopped=storyPaused||motionPaused;$('#story-autoplay').setAttribute('aria-pressed',String(stopped));$('#story-autoplay').setAttribute('aria-label',stopped?'开启章节自动切换':'暂停章节自动切换');$('#story-autoplay span').textContent=stopped?'OFF':'ON';}
function scheduleStory(delay=8000){clearTimeout(storyTimer);updateStoryAutoplay();if(storyPaused||motionPaused||!storyVisible||storyHovered||storyFocused||document.hidden||$$('dialog[open]').length)return;storyTimer=setTimeout(()=>selectStory((storyIndex+1)%4,false),delay);}
function selectStory(index,manual=false){storyIndex=(index+4)%4;storyPanels.forEach((panel,i)=>{const active=i===storyIndex;panel.classList.toggle('is-active',active);panel.style.transform=`translateX(${(i-storyIndex)*100}%)`;panel.setAttribute('aria-hidden',String(!active));panel.inert=!active;$$('.reveal',panel).forEach(el=>el.classList.add('in-view'));if(active)$$('img',panel).forEach(img=>img.loading='eager');});storyTabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===storyIndex));tab.tabIndex=i===storyIndex?0:-1;});$('#story-counter').textContent=`0${storyIndex+1} / 04`;if(manual){$('#story-announcement').textContent=`第${storyIndex+1}章：${storyNames[storyIndex]}`;history.replaceState(null,'',`#act${storyIndex+1}`);}sizeStory();scheduleStory(manual?12000:8000);}
storyTabs.forEach(tab=>tab.addEventListener('click',()=>selectStory(Number(tab.dataset.chapter),true)));wireTabKeys($('.chapter-nav'));
$('#story-prev').addEventListener('click',()=>selectStory(storyIndex-1,true));$('#story-next').addEventListener('click',()=>selectStory(storyIndex+1,true));
$('#story-autoplay').addEventListener('click',()=>{if(motionPaused){motionPaused=false;updateMotion();storyPaused=false;}else storyPaused=!storyPaused;scheduleStory();});
storyViewport.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'){storyHovered=true;scheduleStory();}});storyViewport.addEventListener('pointerleave',()=>{storyHovered=false;scheduleStory();});
storyViewport.addEventListener('focusin',()=>{storyFocused=true;scheduleStory();});storyViewport.addEventListener('focusout',event=>{if(!storyViewport.contains(event.relatedTarget)){storyFocused=false;scheduleStory();}});
new IntersectionObserver(entries=>{storyVisible=entries[0].isIntersecting;scheduleStory();},{threshold:.2}).observe(storyViewport);
new ResizeObserver(()=>requestAnimationFrame(sizeStory)).observe(storyPanels[0]);storyPanels.slice(1).forEach(panel=>new ResizeObserver(()=>requestAnimationFrame(sizeStory)).observe(panel));
addEventListener('resize',sizeStory);document.fonts.ready.then(sizeStory);document.addEventListener('visibilitychange',()=>scheduleStory());document.addEventListener('motionchange',()=>scheduleStory());
$$('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>scheduleStory());new MutationObserver(()=>scheduleStory()).observe(dialog,{attributes:true,attributeFilter:['open']});});
