const ca=$('#candidate-a'),cb=$('#candidate-b');let comparisonIndex=0,compareWanted=false,compareFrame=0;let syncSeek=0;
function syncRange(){const durations=[ca.duration,cb.duration].filter(Number.isFinite);if(durations.length===2)$('#compare-range').max=Math.floor(Math.min(...durations)*1000);}
function ensureSources(){const c=comparisons[comparisonIndex];[ca,cb].forEach((v,i)=>{if(!v.getAttribute('src')){v.src=`assets/video/${i?c.b:c.a}.mp4`;v.load();}});}
[ca,cb].forEach(v=>{v.addEventListener('loadedmetadata',()=>{syncRange();v.currentTime=Math.min(syncSeek,v.duration-.02);});v.addEventListener('ended',()=>{pauseCandidates();cancelAnimationFrame(compareFrame);});v.addEventListener('error',()=>{pauseCandidates();$('#compare-copy').textContent='候选片段暂时无法播放，可在下方素材档案中重新打开。';});});
